#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // Last index of the longest strictly increasing prefix.
    int left = 0;
    while (left + 1 < n && a[left] < a[left + 1]) left++;
    if (left == n - 1) { printf("%lld\n", (long long)n * (n + 1) / 2); return 0; }
    // Start of the longest strictly increasing suffix.
    int right = n - 1;
    while (right > 0 && a[right - 1] < a[right]) right--;
    long long ans = 0;
    int j = right;
    // Keep prefix a[0..i-1]; j is the earliest suffix start that joins it strictly.
    for (int i = 0; i < left + 2; i++) {
        j = max(j, i + 1);
        if (i) while (j < n && a[j] <= a[i - 1]) j++;
        ans += n - j + 1;
    }
    printf("%lld\n", ans);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Last index of the longest strictly increasing prefix.
        int left = 0;
        while (left + 1 < n && a[left] < a[left + 1]) left++;
        if (left == n - 1) { System.out.println((long) n * (n + 1) / 2); return; }
        // Start of the longest strictly increasing suffix.
        int right = n - 1;
        while (right > 0 && a[right - 1] < a[right]) right--;
        long ans = 0;
        int j = right;
        // Keep prefix a[0..i-1]; j is the earliest suffix start that joins it strictly.
        for (int i = 0; i < left + 2; i++) {
            j = Math.max(j, i + 1);
            if (i > 0) while (j < n && a[j] <= a[i - 1]) j++;
            ans += n - j + 1;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	// Last index of the longest strictly increasing prefix.
	left := 0
	for left+1 < n && a[left] < a[left+1] {
		left++
	}
	if left == n-1 {
		fmt.Println(n * (n + 1) / 2)
		return
	}
	// Start of the longest strictly increasing suffix.
	right := n - 1
	for right > 0 && a[right-1] < a[right] {
		right--
	}
	ans, j := 0, right
	// Keep prefix a[0..i-1]; j is the earliest suffix start that joins it strictly.
	for i := 0; i < left+2; i++ {
		j = max(j, i+1)
		if i > 0 {
			for j < n && a[j] <= a[i-1] {
				j++
			}
		}
		ans += n - j + 1
	}
	fmt.Println(ans)
}
